import axios from "axios";

// Base URL configuration clearly defined
const API_BASE_URL = process.env.REACT_APP_API_URL || "http://localhost:5000/api/delivery";

// Fetch all deliveries
export const fetchDeliveries = () => axios.get(`${API_BASE_URL}`);

// Assign a driver to a specific delivery
export const assignDriver = (deliveryId: string, driverId: string) =>
  axios.put(`${API_BASE_URL}/${deliveryId}/assign`, { driverId });

// Get details of a specific delivery by its ID
export const getDeliveryById = (id: string) =>
  axios.get(`${API_BASE_URL}/${id}`);

// Create a new delivery (optional for completeness)
export const createDelivery = (data: { customerId: string; driverId: string; location: { lat: number; lng: number }; status: string }) =>
  axios.post(`${API_BASE_URL}`, data);

// Update delivery status (optional for completeness)
export const updateDeliveryStatus = (deliveryId: string, status: string) =>
  axios.put(`${API_BASE_URL}/status`, { deliveryId, status });
